import {  Injectable } from "@angular/core";
import { map, Observable } from "rxjs";
import { PermissionConverterFnc, UBCKPermissionModel } from "./base/model";

export abstract class PermissionServiceContract{

    protected abstract getPermissions(): Observable<UBCKPermissionModel[]>;
    protected abstract converter: PermissionConverterFnc;
}

//  demo implementation of PermissionService with contract
@Injectable({
    providedIn: 'root'
})
export class PermissionService extends PermissionServiceContract {

    override getPermissions(): Observable<UBCKPermissionModel[]> {
        return new Observable<UBCKPermissionModel[]>((observer) => {
            setTimeout(() => {
                observer.next(Array.from({ length: 1000 }, (_v, k) => {
                    return {
                        permission_id: `permission_${k}`,
                        description: `Description for permission_${k}`
                    }
                }) as any);
                 observer.complete();
            }, 3000)
           
        }).pipe(map((data) => this.converter(data)));
    }
    override converter: PermissionConverterFnc = <T>(arg: T): UBCKPermissionModel[] => {
        let argument: {permission_id: string, description: string}[] = arg as unknown as {permission_id: string, description: string}[];
        return  argument.map(item => {
            return {
                permission: item.permission_id,
                description: item.description
            }
        });
    }

}