import { Directive, effect, ElementRef, inject, input, signal, TemplateRef, ViewContainerRef } from "@angular/core";
import { PermissionStore } from "../services/permission/permission-store";

@Directive({
    standalone: true,
    selector: '[withPermissions]',
    exportAs: 'withPermissions'
})
export class WithPermission {
    hasPermission = signal(false);
    requirePermission = input.required<string[]>({
        alias: 'withPermissions'
    });

    private readonly permissionStore = inject(PermissionStore);
    public readonly viewContainerRef = inject(ViewContainerRef);
    public readonly elementRef = inject(ElementRef);
    public templateRef = inject(TemplateRef<any>, { optional: true });

    permissionCheck = effect(() => {
        if (!this.templateRef) {
            console.warn('withPermissions directive requires a TemplateRef. Please use it on an ng-template element.');
            return;
        }

        this.viewContainerRef.clear();
        this.viewContainerRef.createEmbeddedView(this.templateRef);
        const hasPermission = (this.permissionStore.permissionsSet()).some(p => this.requirePermission().includes(p));
        this.hasPermission.set(hasPermission);
    })
}