import {  inject, Injectable, signal, WritableSignal } from "@angular/core";
import { PermissionService } from "./permission-service";
import { map, Observable, take } from "rxjs";
import { UBCKPermissionModel } from "./base/model";

export abstract class PermissionStoreContract {
    abstract permissions: WritableSignal<UBCKPermissionModel[]>;
    abstract permissionsSet: WritableSignal<string[]>;
    abstract canAccess(permission: string | string[]): boolean;
    abstract loadPermissions(): void;
    abstract getPermissionAsync(): Observable<UBCKPermissionModel[]>;
    abstract getPermissionSetAsync(): Observable<string[]>;

    abstract setPermissions(permissions: UBCKPermissionModel[]): void;
    abstract loadPermissionsObservable(): Observable<UBCKPermissionModel[]>;
}

/**
 * PermissionStore service implementing the PermissionStoreContract.
 * Provides methods to manage and retrieve permissions.
 */

@Injectable({
    providedIn: 'root'
})
export class PermissionStore extends PermissionStoreContract {
    override readonly permissions = signal<UBCKPermissionModel[]>([])
    override readonly permissionsSet = signal<string[]>([])

    private permissionService = inject(PermissionService);


    override loadPermissions(): void {
        this.loadPermissionsObservable().subscribe();
    }

    override loadPermissionsObservable(): Observable<UBCKPermissionModel[]> {
        return this.permissionService.getPermissions().pipe(
            take(1),
            map(res => {
                this.permissions.set(res);
                this.permissionsSet.set(this.permissions()?.map(perm => perm['permission']) || []);
                return res;
            })
        );
    }


    override canAccess(permission: string | string[], type: 'equal' | 'startsWith' = 'equal'): boolean {
        let ok = false;
        const permissionsToCheck = Array.isArray(permission) ? permission : [permission];
        switch (type) {
            case 'equal':
                ok = permissionsToCheck.some(p => this.permissionsSet().includes(p));
                break
            case 'startsWith':
                ok = permissionsToCheck.some(p => this.permissionsSet().some(sp => sp.startsWith(p)));
                break;
        }
        return ok
    }

    override getPermissionAsync(): Observable<UBCKPermissionModel[]> {
        return this.permissionService.getPermissions();
    }


    override getPermissionSetAsync(): Observable<string[]> {
        return this.permissionService.getPermissions().pipe(
            // Map to extract only permission strings
            map(perms => perms.map(perm => perm['permission']))
        );
    }

    override setPermissions(permissions: UBCKPermissionModel[]): void {
        this.permissions.set(permissions);
        this.permissionsSet.set(permissions.map(perm => perm['permission']));
    }




}