/**
 *  Định nghĩa kiểu dữ liệu log thay đổi dữ liệu chung
 */
export interface UbckHistoryChange {
  /**
   * ID của log (UUID)
   */
  logId: string;

  /**
   * Code từ bảng JOIN
   */
  entityCode?: string;

  /**
   * Name từ bảng JOIN
   */
  entityName?: string;

  /**
   * Thời gian cập nhật entity (OffsetDateTime -> JS Date)
   */
  updatedEntityAt?: string | null;

  /**
   * Người cập nhật
   */
  updatedByName?: string;

  /**
   * Nghiệp vụ ghi nhận
   */
  actionCustom?: string;

  /**
   * Chi tiết thay đổi (JSON object or raw string)
   */
  dataChange?: any;
}

//  add thêm loại action CUSTOM_ENUM nếu cần
// không xóa các loại action khác
export const UbckACTION_CUSTOM_ENUM = {
  CREATE: 'CREATE',
  UPDATE: 'UPDATE',
  DELETE: 'DELETE',
} as const;
export type UbckActionCustomType = (typeof UbckACTION_CUSTOM_ENUM)[keyof typeof UbckACTION_CUSTOM_ENUM];

export const UBCK_ACTION_CUSTOM_TRANSFORM_LABEL: Record<UbckActionCustomType, string> = {
  CREATE: 'COMMON.ACTION_TYPE.CREATE',
  UPDATE: 'COMMON.ACTION_TYPE.UPDATE',
  DELETE: 'COMMON.ACTION_TYPE.DELETE',
} as const;
