import { HttpClient, HttpContextToken } from '@angular/common/http';
import { inject, Injectable } from '@angular/core';
import { map, Observable, OperatorFunction } from 'rxjs';
export interface IHttpApiResponse<R> {
  data: R;
  httpStatus: string;
  resultCode: number;
  resultMsg: string;
  correlationId: string;
  responseTimestamp: string;
}
export type HttpRequestMetadata = {
  [key: string]: unknown;
  ignoreLoadingIndicator?: boolean;
  ignoreErrorHandler?: boolean;
  ignoreRefreshToken?: boolean;
  crudHandlerType?: 'create' | 'read' | 'update' | 'delete';
};

export abstract class HttpApiServiceConfig {
  abstract get<R>(
    baseUrl: string | null,
    endpoint: string,
    options?: { [key: string]: unknown },
  ): Observable<R>;
  abstract post<R, T>(
    baseUrl: string | null,
    body: T,
    endpoint: string,
    options?: { [key: string]: unknown },
  ): Observable<R>;
  abstract put<R, T>(
    baseUrl: string | null,
    body: T,
    endpoint: string,
    options?: { [key: string]: unknown },
  ): Observable<R>;
  abstract delete<R>(
    baseUrl: string | null,
    endpoint: string,
    options?: { [key: string]: unknown },
  ): Observable<R>;
  abstract patch<R, T>(
    baseUrl: string | null,
    body: T,
    endpoint: string,
    options?: { [key: string]: unknown },
  ): Observable<R>;
}

@Injectable({
  providedIn: 'root',
})
export class HttpApiService extends HttpApiServiceConfig {
  private http = inject(HttpClient);
  public static REQUEST_ID = new HttpContextToken<string>(() => 'REQUEST_ID');
  public static HTTP_METADATA: HttpContextToken<HttpRequestMetadata> =
    new HttpContextToken<HttpRequestMetadata>(() => ({
      ignoreLoadingIndicator: false,
      ignoreErrorHandler: false,
      ignoreRefreshToken: false,
    }));
  protected environment: { apiUrl: string } & Record<string, unknown> = {
    apiUrl: '',
  };
  protected transformerResponse<T>(): OperatorFunction<IHttpApiResponse<T>, T> {
    return map((response) => response.data);
  }

  override get<R>(
    baseUrl: string | null,
    endpoint: string,
    options: { [key: string]: unknown } = {},
  ): Observable<R> {
    const api = this.handleParseUrl(baseUrl, endpoint, options);
    return this.http
      .get<IHttpApiResponse<R>>(api, options)
      .pipe(this.transformerResponse<R>());
  }

  override post<R, T>(
    baseUrl: string | null,
    body: T,
    endpoint: string,
    options: { [key: string]: unknown } = {},
  ): Observable<R> {
    const api = this.handleParseUrl(baseUrl, endpoint, options);
    return this.http
      .post<IHttpApiResponse<R>>(api, body, options)
      .pipe(this.transformerResponse<R>());
  }

  override put<R, T>(
    baseUrl: string | null,
    body: T,
    endpoint: string,
    options: { [key: string]: unknown } = {},
  ): Observable<R> {
    const api = this.handleParseUrl(baseUrl, endpoint, options);
    return this.http
      .put<IHttpApiResponse<R>>(api, body, options)
      .pipe(this.transformerResponse<R>());
  }

  delete<R>(
    baseUrl: string | null,
    endpoint: string,
    options: { [key: string]: unknown } = {},
  ): Observable<R> {
    const api = this.handleParseUrl(baseUrl, endpoint, options);
    return this.http
      .delete<IHttpApiResponse<R>>(api, options)
      .pipe(this.transformerResponse<R>());
  }

  patch<R, T>(
    baseUrl: string | null,
    body: T,
    endpoint: string,
    options: { [key: string]: unknown } = {},
  ): Observable<R> {
    const api = this.handleParseUrl(baseUrl, endpoint, options);
    return this.http
      .patch<IHttpApiResponse<R>>(api, body, options)
      .pipe(this.transformerResponse<R>());
  }

  handleParseUrl(
    baseUrl: string | null,
    endpoint: string,
    options: { [key: string]: unknown } = {},
  ): string {
    const keys = Object.keys(options);
    let finalEndpoint = endpoint;
    let finalBaseUrl = baseUrl;
    let api = '';
    for (const key of keys) {
      finalEndpoint = finalEndpoint.replace(`{${key}}`, options[key] as string);
    }
    if (!finalBaseUrl) {
      finalBaseUrl = this.environment.apiUrl;
    }
    api = finalBaseUrl + finalEndpoint;
    return api;
  }
}
