import { TranslateService } from "@ngx-translate/core";
import { PrimeNG } from "primeng/config";
import Language from "./lang";
import { InjectionToken } from "@angular/core";


export const PRIMENG_TRANSLATE = new InjectionToken<PrimeNG>('PRIMENG_TRANSLATE');

export function primeNGTranslateFactory(translateService: TranslateService, primeng: PrimeNG) {
    primeng.setTranslation(Language.vi); // default language    
    translateService.onLangChange.subscribe((lang) => {
        const newLang =  Language[lang.lang as keyof typeof Language] || Language.vi;   
        primeng.setTranslation(newLang);
    });
    return primeng;
}